    count_map = {}
    output = []
    for _ in range(q):
        parts = sys.stdin.readline().split()
        if parts[0] == '1':
            x = int(parts[1])
            if x in count_map:
                count_map[x] += 1
            else:
                count_map[x] = 1
        elif parts[0] == '2':
            x = int(parts[1])
            count_map[x] -= 1
            if count_map[x] == 0:
                del count_map[x]
        elif parts[0] == '3':
            output.append(str(len(count_map)))
    print('\n'.join(output))

